/******************************************************************************
 * @file            ld.h
 *****************************************************************************/
#ifndef     _LD_H
#define     _LD_H

#define     FAKE_LD_FILENAME            "autogenerated"
#include    "stdint.h"

struct ld_state {

    const char **input_files;
    long nb_input_files;
    
    const char *entry_symbol_name;
    uint64_t entry_point;
    
    const char *output_map_filename;
    uint64_t base_address;
    
    const char *output_filename;
    int create_shared_library, format;
    
    int emit_relocs, use_custom_base_address;
    unsigned long size_of_headers;
    
    int emulation, generate_symbols_table, impure;
    int leading_underscore;

};


#define     LD_TARGET_MACHINE_AARCH64                       (1U << 14)
#define     LD_TARGET_MACHINE_AMD64                         (1U << 13)
#define     LD_TARGET_MACHINE_I386                          (1U << 12)


#define     LD_EMULATION_NONE           0x00

#define     LD_EMULATION_IA16_DX        0x01
#define     LD_EMULATION_IA16_MZ        0x02

#define     LD_EMULATION_I386_AOUT      0x03
#define     LD_EMULATION_I386_COFF      0x04
#define     LD_EMULATION_I386_DX        0x05
#define     LD_EMULATION_I386_PE        0x06

#define     LD_EMULATION_AXE            0x07
#define     LD_EMULATION_MACHO          0x08


#define     LD_FORMAT_COM               0x00
#define     LD_FORMAT_MZ                0x01
#define     LD_FORMAT_BIN               0x02

#define     LD_FORMAT_IA16_ELKS         0x03
#define     LD_FORMAT_IA16_DX           0x04

#define     LD_FORMAT_I386_ELKS         (LD_TARGET_MACHINE_I386     | 0x05)
#define     LD_FORMAT_I386_DX           (LD_TARGET_MACHINE_I386     | 0x06)
#define     LD_FORMAT_I386_AOUT         (LD_TARGET_MACHINE_I386     | 0x07)
#define     LD_FORMAT_I386_COFF         (LD_TARGET_MACHINE_I386     | 0x08)
#define     LD_FORMAT_I386_PE           (LD_TARGET_MACHINE_I386     | 0x09)
#define     LD_FORMAT_I386_ELF          (LD_TARGET_MACHINE_I386     | 0x10)
#define     LD_FORMAT_I386_AXE          (LD_TARGET_MACHINE_I386     | 0x11)

#define     LD_FORMAT_AMD64_MACHO       (LD_TARGET_MACHINE_AMD64    | 0x12)
#define     LD_FORMAT_AMD64_ELF         (LD_TARGET_MACHINE_AMD64    | 0x13)
#define     LD_FORMAT_AMD64_PE          (LD_TARGET_MACHINE_AMD64    | 0x14)
#define     LD_FORMAT_AMD64_AXE         (LD_TARGET_MACHINE_AMD64    | 0x15)

#define     LD_FORMAT_AARCH64_MACHO     (LD_TARGET_MACHINE_AARCH64  | 0x16)
#define     LD_FORMAT_AARCH64_ELF       (LD_TARGET_MACHINE_AARCH64  | 0x17)


extern struct ld_state *state;
extern const char *program_name;

#define     DEFAULT_SECTION_ALIGNMENT       0x1000
#define     DEFAULT_FILE_ALIGNMENT          0x0200

void map_write (const char *filename);
void link (void);

#endif      /* _LD_H */
